import html
import re


def parse_price(s: str) -> float | None:
    if not isinstance(s, str):
        return None

    s = html.unescape(s).strip()
    if not s:
        return None

    lowered = s.lower()
    if "bied" in lowered:
        return None
    if "gratis" in lowered:
        return 0.0

    # Remove whitespace and everything except digits, dots, and commas.
    t = "".join(s.split())
    t = re.sub(r"[^0-9,.]", "", t)
    if not t:
        return None

    # Dutch prices often end with ",-" meaning no cents.
    while t.endswith(","):
        t = t[:-1]
        if not t:
            return None

    if "," in t:
        integer_part, decimal_part = t.split(",", 1)
        if "," in decimal_part:
            return None

        integer_part = integer_part.replace(".", "")
        decimal_part = decimal_part.replace(".", "")

        if integer_part == "":
            integer_part = "0"

        if not integer_part.isdigit() or (decimal_part and not decimal_part.isdigit()):
            return None

        if decimal_part:
            return float(f"{integer_part}.{decimal_part}")
        return float(integer_part)

    if "." in t:
        # Standard Dutch thousands grouping: 1.250.500
        if re.fullmatch(r"\d{1,3}(?:\.\d{3})+", t):
            t = t.replace(".", "")
        # Fall back to treating a single dot as a decimal point.
        elif re.fullmatch(r"\d+\.\d+", t):
            return float(t)
        elif re.fullmatch(r"\.\d+", t):
            return float(t)
        elif re.fullmatch(r"\d+\.", t):
            return float(t)
        else:
            t = t.replace(".", "")

    if t.isdigit():
        return float(t)

    return None

