import re


def parse_price(s: str) -> float | None:
    if not isinstance(s, str):
        return None

    text = s.strip()
    if not text:
        return None

    lowered = text.lower()
    if "gratis" in lowered:
        return 0.0
    if "bieden" in lowered:
        return None

    text = text.replace("\u00a0", "")
    text = re.sub(r"€|euro|eur|\s", "", text, flags=re.IGNORECASE)
    text = re.sub(r",-$", "", text)
    text = text.rstrip("-")

    if not text:
        return None

    sign = 1.0
    if text[0] in "+-":
        if text[0] == "-":
            sign = -1.0
        text = text[1:]
        if not text:
            return None

    if "," in text:
        if text.count(",") > 1:
            return None

        integer_part, fraction_part = text.split(",")

        if integer_part and not re.fullmatch(r"\d{1,3}(?:\.\d{3})*|\d+", integer_part):
            return None
        if not re.fullmatch(r"\d*", fraction_part):
            return None
        if not integer_part and not fraction_part:
            return None

        integer_part = integer_part.replace(".", "") or "0"

        if fraction_part:
            return sign * float(f"{integer_part}.{fraction_part}")
        return sign * float(integer_part)

    if "." in text:
        if re.fullmatch(r"\d{1,3}(?:\.\d{3})+", text):
            text = text.replace(".", "")
        elif re.fullmatch(r"\d+\.\d+", text):
            return sign * float(text)
        elif re.fullmatch(r"\d+\.", text):
            text = text[:-1]
        else:
            return None

    if not re.fullmatch(r"\d+", text):
        return None

    return sign * float(text)

