import datetime


def next_pickup_slot(now: datetime.datetime) -> datetime.datetime:
    candidate = now.replace(second=0, microsecond=0)
    minute_offset = (30 - candidate.minute) % 30

    if minute_offset:
        candidate += datetime.timedelta(minutes=minute_offset)

    if candidate < now:
        candidate += datetime.timedelta(minutes=30)

    tzinfo = now.tzinfo

    for offset in range(8):
        day = now.date() + datetime.timedelta(days=offset)
        weekday = day.weekday()

        if weekday == 6:
            continue

        if weekday == 5:
            start_hour, end_hour = 10, 16
        else:
            start_hour, end_hour = 18, 21

        first = datetime.combine(
            day,
            datetime.time(start_hour, 0),
            tzinfo=tzinfo
        )
        last = datetime.combine(
            day,
            datetime.time(end_hour, 0),
            tzinfo=tzinfo
        ) - datetime.timedelta(minutes=30)

        if offset == 0:
            slot = candidate if candidate >= first else first
        else:
            slot = first

        if slot <= last:
            return slot

    raise RuntimeError("No pickup slot found")

